'use strict';

/**
* Compute one DQD transform in ping-pong form.
*
* ## Notes
*
* -   `Z` is a 1-D array of length >= `4 * N0` storing interleaved Q/E values.
* -   `PP` is 0 for ping, 1 for pong.
*
* @module @stdlib/lapack/base/dlasq6
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlasq6 = require( '@stdlib/lapack/base/dlasq6' );
*
* var out = new Float64Array( 6 );
* var Z = new Float64Array( [ 5, 0, 7, 0, 9, 0, 3, 0, 11, 0, 4, 0, 20, 0, 0, 0 ] );
*
* dlasq6( 0, 3, Z, 0, out );
* // out => <Float64Array>[ 3.75, 3.75, 3.75, ~12.088, ~6.111, 3.75 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlasq6 = require( '@stdlib/lapack/base/dlasq6' );
*
* var out = new Float64Array( 6 );
* var Z = new Float64Array( [ 5, 0, 7, 0, 9, 0, 3, 0, 11, 0, 4, 0, 20, 0, 0, 0 ] );
*
* dlasq6.ndarray( 0, 3, Z, 1, 0, 0, out, 1, 0 );
* // out => <Float64Array>[ 3.75, 3.75, 3.75, ~12.088, ~6.111, 3.75 ]
*/


// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlasq6;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlasq6 = main;
} else {
	dlasq6 = tmp;
}


// EXPORTS //

module.exports = dlasq6;

// exports: { "ndarray": "dlasq6.ndarray" }
